CREATE TABLE rm_party_alias_assertions (
 id INTEGER PRIMARY KEY, party_id TEXT NOT NULL, alias TEXT NOT NULL, source TEXT NOT NULL, observed_at TEXT NOT NULL, review_state TEXT NOT NULL CHECK(review_state IN ('proposed','approved','rejected')), payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64 AND payload_hash NOT GLOB '*[^0-9a-f]*'), actor TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(party_id,payload_hash)
);
CREATE TABLE rm_party_field_assertions (
 id INTEGER PRIMARY KEY, party_id TEXT NOT NULL, field TEXT NOT NULL, value TEXT NOT NULL, source TEXT NOT NULL, observed_at TEXT NOT NULL, review_state TEXT NOT NULL CHECK(review_state IN ('proposed','approved','rejected')), payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64 AND payload_hash NOT GLOB '*[^0-9a-f]*'), actor TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(party_id,payload_hash)
);
CREATE TABLE rm_party_legacy_links (
 company_slug TEXT NOT NULL, legacy_kind TEXT NOT NULL CHECK(legacy_kind IN ('customer','vendor')), legacy_id TEXT NOT NULL, party_id TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(company_slug,legacy_kind,legacy_id)
);
CREATE TRIGGER rm_party_alias_assertions_no_update BEFORE UPDATE ON rm_party_alias_assertions BEGIN SELECT RAISE(ABORT, 'party alias assertions are append-only'); END;
CREATE TRIGGER rm_party_alias_assertions_no_delete BEFORE DELETE ON rm_party_alias_assertions BEGIN SELECT RAISE(ABORT, 'party alias assertions are append-only'); END;
CREATE TRIGGER rm_party_field_assertions_no_update BEFORE UPDATE ON rm_party_field_assertions BEGIN SELECT RAISE(ABORT, 'party field assertions are append-only'); END;
CREATE TRIGGER rm_party_field_assertions_no_delete BEFORE DELETE ON rm_party_field_assertions BEGIN SELECT RAISE(ABORT, 'party field assertions are append-only'); END;
CREATE TRIGGER rm_party_legacy_links_no_update BEFORE UPDATE ON rm_party_legacy_links BEGIN SELECT RAISE(ABORT, 'party legacy links are append-only'); END;
CREATE TRIGGER rm_party_legacy_links_no_delete BEFORE DELETE ON rm_party_legacy_links BEGIN SELECT RAISE(ABORT, 'party legacy links are append-only'); END;
